(async () => {
  const page = await figma.getNodeByIdAsync("0:1");
  if (!page) {
    console.log("Page 0:1 not found");
    return;
  }

  // Find all text nodes in the page to read the instructions
  const texts = page.findAll(node => node.type === "TEXT");
  const sortedTexts = texts.sort((a, b) => {
    // Sort primarily by y, then by x
    const ay = a.absoluteTransform ? a.absoluteTransform[1][2] : 0;
    const by = b.absoluteTransform ? b.absoluteTransform[1][2] : 0;
    const ax = a.absoluteTransform ? a.absoluteTransform[0][2] : 0;
    const bx = b.absoluteTransform ? b.absoluteTransform[0][2] : 0;
    if (Math.abs(ay - by) < 10) return ax - bx;
    return ay - by;
  });

  const output = sortedTexts.map(t => `[${t.name}]: ${t.characters}`).join("\n\n");
  console.log("=== TEXTS ON START HERE PAGE ===");
  console.log(output.substring(0, 10000));
})();

async function run() {
  const page = await figma.getNodeByIdAsync("0:1");
  if (!page) {
    return "Page 0:1 not found";
  }

  const texts = page.findAll(node => node.type === "TEXT");
  // Sort by visual reading order
  texts.sort((a, b) => {
    const ay = a.absoluteRenderBounds ? a.absoluteRenderBounds.y : 0;
    const by = b.absoluteRenderBounds ? b.absoluteRenderBounds.y : 0;
    const ax = a.absoluteRenderBounds ? a.absoluteRenderBounds.x : 0;
    const bx = b.absoluteRenderBounds ? b.absoluteRenderBounds.x : 0;
    if (Math.abs(ay - by) < 15) return ax - bx;
    return ay - by;
  });

  return texts.map(t => `${t.characters}`).join("\n---\n");
}
return await run();

async function inspectPages() {
  const result = {};

  // Inspect 01 · Foundations
  const p1 = await figma.getNodeByIdAsync("1:2");
  if (p1) {
    const texts = p1.findAll(n => n.type === "TEXT").map(t => t.characters);
    result.foundations = texts.slice(0, 30);
  }

  // Inspect 02 · Components
  const p2 = await figma.getNodeByIdAsync("1:3");
  if (p2) {
    result.components = p2.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type,
      width: c.width,
      height: c.height
    }));
  }

  // Inspect 04 · Media
  const p4 = await figma.getNodeByIdAsync("1:4");
  if (p4) {
    result.media = p4.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type
    }));
  }

  // Inspect 03 · Workspace
  const p3 = await figma.getNodeByIdAsync("3:2");
  if (p3) {
    result.workspace = p3.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type
    }));
  }

  return JSON.stringify(result, null, 2);
}
return await inspectPages();

async function run() {
  const compFrame = await figma.getNodeByIdAsync("1:19");
  const mediaFrame = await figma.getNodeByIdAsync("1:125");

  const compChildren = compFrame ? compFrame.children.map(c => ({ id: c.id, name: c.name, type: c.type })) : [];
  const mediaChildren = mediaFrame ? mediaFrame.children.map(c => ({ id: c.id, name: c.name, type: c.type })) : [];

  return JSON.stringify({
    components: compChildren,
    media: mediaChildren
  }, null, 2);
}
return await run();

