    const node = await figma.getNodeByIdAsync(id);
    if (node) {
      result[node.name] = node.children.map(c => ({ id: c.id, name: c.name, type: c.type, width: c.width, height: c.height }));
    }
  }
  return JSON.stringify(result, null, 2);
}
return await run();

async function run() {
  const btn = await figma.getNodeByIdAsync("1:23");
  const tf = await figma.getNodeByIdAsync("1:26");

  function dump(node) {
    return {
      id: node.id,
      name: node.name,
      type: node.type,
      width: node.width,
      height: node.height,
      layoutMode: node.layoutMode,
      paddingLeft: node.paddingLeft,
      paddingRight: node.paddingRight,
      paddingTop: node.paddingTop,
      paddingBottom: node.paddingBottom,
      itemSpacing: node.itemSpacing,
      primaryAxisAlignItems: node.primaryAxisAlignItems,
      counterAxisAlignItems: node.counterAxisAlignItems,
      fills: node.fills,
      strokes: node.strokes,
      strokeWeight: node.strokeWeight,
      cornerRadius: node.cornerRadius,
      children: node.children ? node.children.map(c => ({
        id: c.id,
        name: c.name,
        type: c.type,
        characters: c.characters,
        fontSize: c.fontSize,
        fontName: c.fontName,
        fills: c.fills
      })) : []
    };
  }

  return JSON.stringify({
    Button: dump(btn),
    TextField: dump(tf)
  }, null, 2);
}
return await run();

