      id: node.id,
      name: node.name,
      type: node.type,
      width: node.width,
      height: node.height,
      fills: node.fills,
      children: node.children ? node.children.map(c => ({ id: c.id, name: c.name, type: c.type, fills: c.fills, strokes: c.strokes })) : []
    };
  }

  return JSON.stringify({
    iconArrowRight: inspectNode(iconArrowRight),
    logoSpotify: inspectNode(logoSpotify),
    photo1: inspectNode(photo1),
    avatarJakob: inspectNode(avatarJakob)
  }, null, 2);
}
return await run();

