async function checkFonts() {
  const fonts = [
    { family: "Hanken Grotesk", style: "Regular" },
    { family: "Hanken Grotesk", style: "Medium" },
    { family: "Hanken Grotesk", style: "SemiBold" },
    { family: "Hanken Grotesk", style: "Bold" },
    { family: "Hanken Grotesk", style: "Semi Bold" },
    { family: "Hanken Grotesk", style: "Extra Bold" },
    { family: "Inter", style: "Regular" },
    { family: "Inter", style: "Semi Bold" },
    { family: "Inter", style: "Bold" }
  ];
  const results = [];
  for (const f of fonts) {
    try {
      await figma.loadFontAsync(f);
      results.push({ ...f, loaded: true });
    } catch (e) {
      results.push({ ...f, loaded: false, error: e.message });
    }
  }
  return JSON.stringify(results, null, 2);
}
return await checkFonts();

