async function checkSocialIconFills() {
  const p3 = await figma.getNodeByIdAsync("3:2");
  const comp = await figma.getNodeByIdAsync("1:94"); // Icon_Instagram
  const inst = comp.createInstance();
  p3.appendChild(inst);

  // Can we override fill on child vector of instance?
  const vec = inst.children[0];
  let overridden = false;
  try {
    vec.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
    overridden = true;
  } catch (e) {
    overridden = false;
  }
  inst.remove();
  return { overridden };
}
