  function getMediaInstance(name) {
    const p4 = figma.getNodeById("1:4");
    const found = p4.findOne(n => n.name === name && n.type === "COMPONENT");
    return found ? found.createInstance() : null;
  }

  function recolorIcon(inst, colorHex) {
    const color = {
      r: parseInt(colorHex.substring(1,3), 16) / 255,
      g: parseInt(colorHex.substring(3,5), 16) / 255,
      b: parseInt(colorHex.substring(5,7), 16) / 255
    };
    inst.findAll(n => n.type === "VECTOR").forEach(v => {
      v.fills = [{ type: 'SOLID', color }];
    });
  }

