async function wirePrototypeInteractions() {
  const p3 = await figma.getNodeByIdAsync("3:2");

  // Find all 7 frames
  const f1 = p3.findChild(c => c.name === "01_Frontpage");
  const f2 = p3.findChild(c => c.name === "02_Magazine");
  const f3 = p3.findChild(c => c.name === "03_Magazine_Post");
  const f4 = p3.findChild(c => c.name === "04_Podcast");
  const f5 = p3.findChild(c => c.name === "05_Podcast_Post");
  const f6 = p3.findChild(c => c.name === "06_Authors");
  const f7 = p3.findChild(c => c.name === "07_Author_Profile");

  if (!f1 || !f2 || !f3 || !f4 || !f5 || !f6 || !f7) {
    return { error: "One or more frames not found" };
  }

  const allFrames = [f1, f2, f3, f4, f5, f6, f7];

  function createNavReaction(targetNodeId) {
    return {
      trigger: { type: "ON_CLICK" },
      actions: [
        {
          type: "NODE",
          destinationId: targetNodeId,
          navigation: "NAVIGATE",
          transition: null
        }
      ]
    };
  }

  let wireCount = 0;

  // 1. Wire Global Header on every frame:
  // - Wordmark -> 01_Frontpage
  // - Magazine nav -> 02_Magazine
  // - Authors nav -> 06_Authors
  // - Podcast nav -> 04_Podcast
  allFrames.forEach(f => {
    // Wordmark
    const wordmark = f.findOne(n => n.name === "Wordmark" && n.type === "TEXT");
    if (wordmark) {
      wordmark.reactions = [createNavReaction(f1.id)];
      wireCount++;
    }

    // Navigation items
    const magLink = f.findOne(n => n.name === "Magazine" && n.type === "TEXT" && n.parent && n.parent.name === "Navigation");
    if (magLink) {
      magLink.reactions = [createNavReaction(f2.id)];
      wireCount++;
    }

    const authLink = f.findOne(n => n.name === "Authors" && n.type === "TEXT" && n.parent && n.parent.name === "Navigation");
    if (authLink) {
      authLink.reactions = [createNavReaction(f6.id)];
      wireCount++;
    }

    const podLink = f.findOne(n => n.name === "Podcast" && n.type === "TEXT" && n.parent && n.parent.name === "Navigation");
    if (podLink) {
      podLink.reactions = [createNavReaction(f4.id)];
      wireCount++;
    }
  });

  // 2. Specific links for 01_Frontpage:
  // - "Hope dies last" -> 03_Magazine_Post
  const hopeFront = f1.findOne(n => n.name === "Hope dies last");
  if (hopeFront) {
    hopeFront.reactions = [createNavReaction(f3.id)];
    wireCount++;
  }

  // - "All articles" -> 02_Magazine
  const allArtFront = f1.findOne(n => n.name === "All articles link");
  if (allArtFront) {
    allArtFront.reactions = [createNavReaction(f2.id)];
    wireCount++;
  }

  // - "Ep 05 card" -> 05_Podcast_Post
  const ep05Front = f1.findOne(n => n.name === "Ep 05");
  if (ep05Front) {
    ep05Front.reactions = [createNavReaction(f5.id)];
    wireCount++;
  }

  // - "All Episodes" -> 04_Podcast
  const allEpFront = f1.findOne(n => n.name === "All Episodes link");
  if (allEpFront) {
    allEpFront.reactions = [createNavReaction(f4.id)];
    wireCount++;
  }

  // - "Louise Jensen" -> 07_Author_Profile
  const louiseFront = f1.findOne(n => n.name === "Louise Jensen");
  if (louiseFront) {
    louiseFront.reactions = [createNavReaction(f7.id)];
    wireCount++;
  }

  // - "All Authors" -> 06_Authors
  const allAuthFront = f1.findOne(n => n.name === "All Authors link");
  if (allAuthFront) {
    allAuthFront.reactions = [createNavReaction(f6.id)];
    wireCount++;
  }

  // 3. Specific links for 02_Magazine:
  // - "Hope dies last card" -> 03_Magazine_Post
  const hopeMag = f2.findOne(n => n.name === "Hope dies last");
  if (hopeMag) {
    hopeMag.reactions = [createNavReaction(f3.id)];
    wireCount++;
  }

  // 4. Specific links for 03_Magazine_Post:
  // - "Go Back" -> 02_Magazine
  const backMag = f3.findOne(n => n.name === "Back Link");
  if (backMag) {
    backMag.reactions = [createNavReaction(f2.id)];
    wireCount++;
  }
  // - "See all" -> 02_Magazine
  const seeAllMag = f3.findOne(n => n.name === "Latest Posts Section")?.findOne(n => n.characters === "See all");
  if (seeAllMag && seeAllMag.parent) {
    seeAllMag.parent.reactions = [createNavReaction(f2.id)];
    wireCount++;
  }

  // 5. Specific links for 04_Podcast:
  // - "Ep 05 Listen" -> 05_Podcast_Post
  const ep05Pod = f4.findOne(n => n.name === "Ep 05");
  if (ep05Pod) {
    const listenLink = ep05Pod.findOne(n => n.name === "LISTEN Link");
    if (listenLink) {
      listenLink.reactions = [createNavReaction(f5.id)];
      wireCount++;
    } else {
      ep05Pod.reactions = [createNavReaction(f5.id)];
      wireCount++;
    }
  }

  // 6. Specific links for 05_Podcast_Post:
  // - "Go Back" -> 04_Podcast
  // - "All Episodes" -> 04_Podcast
  const backPod = f5.findOne(n => n.name === "Back Link");
  if (backPod) {
    backPod.reactions = [createNavReaction(f4.id)];
    wireCount++;
  }
  const allEpPost = f5.findOne(n => n.name === "All Episodes link");
  if (allEpPost) {
    allEpPost.reactions = [createNavReaction(f4.id)];
    wireCount++;
  }

  // 7. Specific links for 06_Authors:
  // - "Louise Jensen About" -> 07_Author_Profile
  const louiseAuth = f6.findOne(n => n.name === "Louise Jensen");
  if (louiseAuth) {
    const aboutLink = louiseAuth.findOne(n => n.name === "ABOUT Link");
    if (aboutLink) {
      aboutLink.reactions = [createNavReaction(f7.id)];
      wireCount++;
    } else {
      louiseAuth.reactions = [createNavReaction(f7.id)];
      wireCount++;
    }
  }

  // 8. Specific links for 07_Author_Profile:
  // - "Go Back" -> 06_Authors
  const backAuth = f7.findOne(n => n.name === "Back Link");
  if (backAuth) {
    backAuth.reactions = [createNavReaction(f6.id)];
    wireCount++;
  }
  // - "The best art museums" -> 03_Magazine_Post
  const bestArtMuseums = f7.findOne(n => n.name === "The best art museums");
  if (bestArtMuseums) {
    bestArtMuseums.reactions = [createNavReaction(f3.id)];
    wireCount++;
  }

  return { success: true, wireCount };
}
return await wirePrototypeInteractions();

